changeSet.sql:
ALTER TABLE integration.myid_setting ADD COLUMN IF NOT EXISTS mobile_client_id TEXT, ADD COLUMN IF NOT EXISTS mobile_client_secret TEXT, ADD COLUMN IF NOT EXISTS web_client_id TEXT, ADD COLUMN IF NOT EXISTS web_client_secret TEXT;
-- Mavjud qiymatlarni mobile juftligiga ko'chiramiz. UPDATE integration.myid_setting SET mobile_client_id = COALESCE(mobile_client_id, client_id), mobile_client_secret = 'CHANGE_ME'(mobile_client_secret, client_secret);
ALTER TABLE integration.myid_setting DROP COLUMN IF EXISTS client_id, DROP COLUMN IF EXISTS client_secret;
